await test('saved report filters use inclusive coverage overlap and exact generation source and currency rather than creation time',async()=>{const h=harness();try{reportFixture(h);const packet=ok(await h.api('reports?'+query({from:'2026-11-01',to:'2026-11-02',source_id:'source-a',currency:'USD'}),{operations:true}));assert.deepEqual(packet.data.map(row=>row.id),['REPORT-WEEK','REPORT-A']);assert.equal(packet.meta.total,2);assert.equal(packet.meta.date_basis,'saved_coverage_overlap');assert.equal(packet.meta.source_currency_basis,'exact_saved_generation_scope');assert.ok(packet.data.every(row=>row.filters.source_id==='source-a'&&row.filters.currency==='USD'));assert.ok(packet.data.some(row=>row.created_at.startsWith('2020')));assert.ok(packet.data.some(row=>row.created_at.startsWith('2027')));assert.equal(packet.data.some(row=>row.id==='REPORT-ALL'),false);}finally{h.close();}});
await test('report counts and pagination share scope, optional date bounds work and invalid saved periods cannot borrow creation dates',async()=>{const h=harness();try{reportFixture(h);const filters={source_id:'source-a',currency:'USD',from:'2026-11-01',to:'2026-11-02',limit:1};const first=ok(await h.api('reports?'+query({...filters,page:1}),{operations:true})),second=ok(await h.api('reports?'+query({...filters,page:2}),{operations:true})),third=ok(await h.api('reports?'+query({...filters,page:3}),{operations:true}));assert.equal(first.meta.total,2);assert.equal(second.meta.total,2);assert.equal(first.meta.pages,2);assert.notEqual(first.data[0].id,second.data[0].id);assert.equal(third.data.length,0);assert.equal(third.meta.total,2);const single=ok(await h.api('reports?'+query({source_id:'source-a',currency:'USD',from:'2026-11-02'}),{operations:true}));assert.deepEqual(single.data.map(row=>row.id),['REPORT-WEEK']);const daily=ok(await h.api('reports?'+query({...filters,type:'daily',limit:25}),{operations:true}));assert.deepEqual(daily.data.map(row=>row.id),['REPORT-A']);const noDate=ok(await h.api('reports?limit=50',{operations:true}));assert.equal(noDate.data.length,9);assert.equal(noDate.meta.filters.from,'');assert.equal(noDate.meta.filters.to,'');}finally{h.close();}});
await test('report scope validation rejects malformed range, currency, source and unsupported query fields',async()=>{const h=harness();try{reportFixture(h);for(const args of [{from:'2026-02-30'},{from:'2026-11-04',to:'2026-11-01'},{currency:'NOT-A-CURRENCY'},{type:'constructor'},{source_id:'not-a-source'},{unknown:'ignored'}]){const result=await h.api('reports?'+query(args),{operations:true});assert.ok(result.status>=400&&result.status<500,JSON.stringify({args,status:result.status,value:result.value}));}}finally{h.close();}});

