 setAttribute(name,value){this.attributes[name]=String(value);if(name.startsWith('data-'))this.dataset[name.slice(5).replace(/-([a-z])/g,(_,letter)=>letter.toUpperCase())]=String(value);if(name==='value')this.value=String(value);if(['disabled','checked','selected','hidden','required'].includes(name))this[name]=true;}
 get name(){return this.getAttribute('name')||'';}set name(value){this.setAttribute('name',value);}
