 matches(selector){return selector.split(',').some(part=>{const pieces=part.trim().split(/\s+(?![^\[]*\])/);if(pieces.length>1){const last=pieces.pop();if(!this.matches(last))return false;let parent=this.parentNode;while(pieces.length){const piece=pieces.pop();while(parent&&!parent.matches(piece))parent=parent.parentNode;if(!parent)return false;parent=parent.parentNode;}return true;}const wanted=pieces[0],tag=wanted.match(/^[a-z][\w-]*/i),id=wanted.match(/#([\w-]+)/),classes=[...wanted.matchAll(/\.([\w-]+)/g)],attrs=[...wanted.matchAll(/\[([\w-]+)(?:=['"]?([^'"\]]+)['"]?)?\]/g)];return(!tag||this.tagName===tag[0])&&(!id||this.getAttribute('id')===id[1])&&classes.every(match=>(this.getAttribute('class')||'').split(/\s+/).includes(match[1]))&&attrs.every(match=>this.hasAttribute(match[1])&&(match[2]===undefined||this.getAttribute(match[1])===match[2]));});}
 closest(selector){let node=this;while(node){if(node.matches(selector))return node;node=node.parentNode;}return null;}
 querySelectorAll(selector){const result=[];for(const child of this.children){if(child.matches(selector))result.push(child);result.push(...child.querySelectorAll(selector));}return result;}querySelector(selector){return this.querySelectorAll(selector)[0]||null;}
 addEventListener(){}removeEventListener(){}focus(){this.focused=true;if(globalThis.document)globalThis.document.activeElement=this;}remove(){if(this.parentNode)this.parentNode.children=this.parentNode.children.filter(node=>node!==this);this.parentNode=null;this.isConnected=false;}contains(node){return node===this||this.children.some(child=>child.contains(node));}close(){this.open=false;}show(){this.open=true;}showModal(){this.open=true;}
