await test('actual emitted conversation picker uses native Agent routing without extra requests or an implicit chat submission',async()=>{for(const lang of ['en','zh']){const h=await intelligenceHarness({lang,params:'id=CON-A'});try{await h.load();const picker=h.page.querySelector('[data-ai-conversation]');assert.equal(picker.tagName,'select');assert.deepEqual(picker.querySelectorAll('option').map(option=>option.getAttribute('value')),['','CON-A','CON-B']);const before=h.requests.length;picker.value='CON-B';await h.dispatch(picker,'change');assert.equal(h.navigations.length,1);assert.equal(h.navigations[0].tab,'agent');assert.equal(h.navigations[0].params.get('id'),'CON-B');assert.equal(h.requests.length,before);picker.value='';await h.dispatch(picker,'change');assert.equal(h.navigations[1].params.size,0);assert.equal(h.requests.length,before);}finally{h.close();}}});
await test('actual emitted friendly provider names retain raw provider values and do not weaken model-key UI permissions',async()=>{for(const lang of ['en','zh'])for(const[role,permissions,demo]of [['owner',{},false],['manager',{model_manage:false},false],['owner',{},true]]){const h=await intelligenceHarness({lang,role,permissions,demo,tab:'models'});try{await h.load();const provider=h.page.querySelector('[name=provider]');assert.deepEqual(provider.querySelectorAll('option').map(option=>option.getAttribute('value')),['openai_compatible','openai','deepseek','mistral','openrouter','custom']);assert.equal(provider.querySelector('option[value=openai_compatible]').textContent,lang==='zh'?'兼容 OpenAI 的服务':'OpenAI-compatible service');assert.equal(provider.querySelector('option[value=custom]').textContent,lang==='zh'?'自定义服务':'Custom endpoint');const key=h.page.querySelector('[name=api_key]');assert.equal(key.getAttribute('type'),'password');assert.equal(key.value,'');assert.equal(key.disabled,role!=='owner'||demo);assert.equal(provider.disabled,role!=='owner');assert.equal(h.page.querySelector('[data-ai=test-model]')===null,role!=='owner');assert.ok(h.requests.every(request=>!request.options.method||request.options.method==='GET'));}finally{h.close();}}const denied=await intelligenceHarness({role:'viewer',tab:'models',permissions:{model_read:false}});try{await denied.load();assert.equal(denied.page.querySelector('[name=api_key]'),null);assert.equal(denied.requests.some(request=>request.path==='intelligence/models'),false);}finally{denied.close();}});
await test('actual emitted Users, Security and Health show supplied sign-in identity and probe time instead of invented activity',async()=>{for(const lang of ['en','zh']){const h=await intelligenceHarness({lang,tab:'users'});try{await h.load();const signed=h.page.querySelectorAll('tr').find(row=>row.textContent.includes('Known sign-in')),never=h.page.querySelectorAll('tr').find(row=>row.textContent.includes('Not yet signed in'));assert.ok(signed.textContent.includes('2026-11-01T04:05:00.000Z'));assert.ok(never.textContent.includes(lang==='zh'?'尚未登录':'Not signed in yet'));h.state.tab='security';await h.load();assert.ok(h.page.textContent.includes(lang==='zh'?'当前登录用户':'Signed in as'));assert.ok(h.page.textContent.includes('Synthetic owner'));h.state.tab='health';await h.load();assert.ok(h.page.textContent.includes(lang==='zh'?'最后检查':'Last checked'));assert.ok(h.page.textContent.includes('2026-11-04T08:10:00.000Z'));assert.ok(!h.page.textContent.includes('2026-11-04T08:09:00.000Z'));assert.ok(h.requests.every(request=>!request.options.method||request.options.method==='GET'));}finally{h.close();}}const viewer=await intelligenceHarness({tab:'users',role:'viewer'});try{await viewer.load();assert.equal(viewer.requests.some(request=>request.path==='team'),false);assert.equal(viewer.page.querySelector('table'),null);}finally{viewer.close();}});
await test('actual emitted Memory source summaries and license history keep human labels alongside the original reference or event code',async()=>{for(const lang of ['en','zh']){const h=await intelligenceHarness({lang,tab:'memory'});try{await h.load();const sources=h.page.querySelectorAll('.knowledge-source-label'),demoSource=sources.find(node=>node.getAttribute('title').startsWith('demo://')),webSource=sources.find(node=>node.getAttribute('title').startsWith('https://'));assert.equal(demoSource.textContent,lang==='zh'?'演示业务记录':'Sample business record');assert.equal(demoSource.getAttribute('title'),'demo://customers/CUS-SYNTHETIC');assert.equal(webSource.textContent,'docs.synthetic.invalid/manual');assert.ok(webSource.getAttribute('title').endsWith('?reference=synthetic'));const detail=h.page.querySelectorAll('[data-ai=memory-detail]').find(node=>node.dataset.id==='MEM-DEMO');await h.dispatch(detail,'click');assert.ok(h.dialog.textContent.includes('demo://customers/CUS-SYNTHETIC'));assert.ok(h.dialog.textContent.includes('Synthetic source content'));h.state.tab='license';h.state.params=new URLSearchParams();await h.load();assert.equal(h.page.querySelector('.admin-event-label').textContent,lang==='zh'?'已激活许可':'License activated');assert.equal(h.page.querySelector('.admin-event-code').textContent,'license.activated');assert.ok(h.page.textContent.includes(lang==='zh'?'未配置验证':'Verification not configured'));assert.ok(h.requests.every(request=>!request.options.method||request.options.method==='GET'));}finally{h.close();}}});
await test('model settings conflict refreshes the visible provider target, clears consent and preserves the unanswered question without provider calls',async()=>{for(const lang of ['en','zh']){let statusReads=0,chatCalls=0;const h=await intelligenceHarness({lang,respond:async(path,options)=>{if(path==='intelligence/status'){statusReads++;return{data:{permissions:{chat:true},model_configured:true,model_target:statusReads===1?{provider:'openai',hostname:'old.synthetic.invalid',model:'old-model',version:1}:{provider:'deepseek',hostname:'new.synthetic.invalid',model:'new-model',version:2}}};}if(path==='intelligence/chat'){chatCalls++;if(chatCalls===1){assert.equal(options.body.model_version,1);const error=Error('Synthetic model settings changed');error.code='MODEL_SETTINGS_CHANGED';throw error;}assert.equal(options.body.model_version,2);throw Error('Synthetic second request intentionally stopped before any provider invocation');}}});try{await h.load();const form=h.page.querySelector('[data-ai-form=chat]'),message=form.querySelector('[name=message]'),useModel=form.querySelector('[name=use_model]'),ack=form.querySelector('[name=summary_send_ack]');message.value='Synthetic unanswered question';useModel.checked=true;ack.checked=true;await h.dispatch(form,'submit');assert.equal(chatCalls,1);assert.equal(statusReads,2);const target=h.page.querySelector('[data-ai-model-target]');assert.ok(target,'Visible model target must have the update hook used by the conflict handler.');assert.ok(target.textContent.includes('DeepSeek'));assert.ok(target.textContent.includes('new.synthetic.invalid'));assert.ok(target.textContent.includes('new-model'));assert.ok(!target.textContent.includes('old.synthetic.invalid'));assert.equal(useModel.checked,false);assert.equal(ack.checked,false);assert.equal(message.value,'Synthetic unanswered question');assert.equal(h.controller.isBusy(),false);assert.equal(form.querySelector('[type=submit]').disabled,false);useModel.checked=true;ack.checked=true;await h.dispatch(form,'submit');assert.equal(chatCalls,2);assert.equal(message.value,'Synthetic unanswered question');assert.ok(h.requests.every(request=>!/^https?:/.test(request.path)));}finally{h.close();}}});

// View behavior here is separate from the real Wrangler full-startup and browser gates.
await test('conversation picker keeps the accepted conversation visible when a dirty or busy route change is refused',async()=>{for(const lang of ['en','zh']){let confirms=0,releaseChat;const pendingChat=new Promise(resolve=>releaseChat=resolve),h=await intelligenceHarness({lang,params:'id=CON-A',confirmLeave:async()=>{confirms++;return false;},respond:async(path)=>path==='intelligence/chat'?pendingChat:undefined});try{await h.load();const picker=h.page.querySelector('[data-ai-conversation]'),form=h.page.querySelector('[data-ai-form=chat]'),message=form.querySelector('[name=message]');message.value='Unsent synthetic draft';const before=h.requests.length;picker.value='CON-B';await h.dispatch(picker,'change');assert.equal(h.navigations.at(-1).params.get('id'),'CON-B');assert.equal(picker.value,'CON-A','A rejected navigation must not make the mobile picker claim conversation B is active.');assert.equal(await h.controller.canLeave(),false);assert.equal(confirms,1);assert.equal(h.state.params.get('id'),'CON-A');assert.equal(message.value,'Unsent synthetic draft');assert.equal(h.requests.length,before);await h.dispatch(form,'submit');assert.equal(h.controller.isBusy(),true);picker.value='';await h.dispatch(picker,'change');assert.equal(h.navigations.at(-1).params.size,0);assert.equal(picker.value,'CON-A');assert.equal(await h.controller.canLeave(),false);assert.equal(confirms,1,'Busy navigation is refused before prompting about the draft.');releaseChat({data:{conversation_id:'CON-A',answer:'Synthetic answer',citations:[]}});await new Promise(resolve=>setImmediate(resolve));assert.equal(h.controller.isBusy(),false);assert.equal(h.requests.filter(request=>request.path==='intelligence/chat').length,1);}finally{h.close();}}});
await test('a successful first Agent answer synchronizes real returned conversation identity without duplicate history or extra reads',async()=>{for(const lang of ['en','zh']){const posts=[],id='CON-SYNTHETIC-CREATED',question='<img src=x onerror=bad()> '+('🧪'.repeat(90)),title=Array.from(question).slice(0,80).join(''),h=await intelligenceHarness({lang,respond:async(path,options)=>{if(path==='intelligence/chat'){posts.push(options.body);return{data:{conversation_id:id,answer:'Synthetic local answer '+posts.length,citations:[]}};}}});try{await h.load();const getCount=h.requests.filter(request=>!request.options.method||request.options.method==='GET').length,form=h.page.querySelector('[data-ai-form=chat]'),message=form.querySelector('[name=message]');message.value=question;await h.dispatch(form,'submit');assert.equal(posts.length,1);assert.equal(posts[0].conversation_id,undefined);assert.equal(posts[0].use_model,false);assert.equal(h.state.params.get('id'),id);const list=h.page.querySelector('[data-ai-conversations]'),picker=h.page.querySelector('[data-ai-conversation]'),href='#agent?id='+id;const links=list.querySelectorAll('a.wb-list-item'),created=links.filter(link=>link.getAttribute('href')===href);assert.equal(created.length,1);assert.equal(links[0],created[0]);assert.equal(created[0].querySelector('strong').textContent,title);assert.equal(Array.from(created[0].querySelector('strong').textContent).length,80);assert.equal(created[0].querySelector('img'),null);assert.equal(created[0].getAttribute('aria-current'),'true');assert.equal(links.filter(link=>link.hasAttribute('aria-current')).length,1);assert.equal(picker.value,id);const option=picker.querySelectorAll('option').filter(node=>node.value===id);assert.equal(option.length,1);assert.equal(option[0].textContent,title);assert.equal(message.value,'');assert.equal(h.controller.hasUnsavedChanges(),false);message.value='A follow-up in the same conversation';await h.dispatch(form,'submit');assert.equal(posts.length,2);assert.equal(posts[1].conversation_id,id);assert.equal(list.querySelectorAll('a.wb-list-item').filter(link=>link.getAttribute('href')===href).length,1);assert.equal(picker.querySelectorAll('option').filter(node=>node.value===id).length,1);assert.equal(created[0].querySelector('strong').textContent,title,'A follow-up must not silently rename the existing conversation.');assert.equal(h.requests.filter(request=>!request.options.method||request.options.method==='GET').length,getCount);assert.ok(h.requests.every(request=>!/^https?:/.test(request.path)));}finally{h.close();}}});

await test('actual emitted report filters reject an inverted range inline while preserving loaded rows, then clear errors and submit the corrected scope',async()=>{const store=harness();try{reportFixture(store);for(const lang of ['en','zh']){const h=await operationsHarness(store,{lang,params:'source_id=source-a&currency=USD'});try{await h.load();const form=h.page.querySelector('[data-op-form=filters]'),from=form.querySelector('[name=from]'),to=form.querySelector('[name=to]'),message=form.querySelector('[data-ops-filter-error]'),rows=h.page.querySelectorAll('tbody')[0].querySelectorAll('tr'),accepted=h.state.params.toString(),before=h.requests.length;assert.ok(rows.length>0);from.value='2026-11-02';to.value='2026-11-01';const rejected=await h.submit(form);assert.equal(rejected.defaultPrevented,true);assert.equal(h.requests.length,before);assert.equal(h.navigations.length,0);assert.equal(h.state.params.toString(),accepted);assert.deepEqual(h.page.querySelectorAll('tbody')[0].querySelectorAll('tr'),rows);assert.equal(from.value,'2026-11-02');assert.equal(to.value,'2026-11-01');assert.equal(message.getAttribute('role'),'alert');assert.equal(message.hidden,false);assert.equal(message.textContent,lang==='zh'?'结束日期不能早于开始日期。':'Choose an end date on or after the start date.');for(const input of [from,to]){assert.equal(input.getAttribute('aria-invalid'),'true');assert.equal(input.getAttribute('aria-errormessage'),message.getAttribute('id'));}to.value='2026-11-04';await h.dispatch(to,'input');for(const input of [from,to]){assert.equal(input.hasAttribute('aria-invalid'),false);assert.equal(input.hasAttribute('aria-errormessage'),false);}assert.equal(message.hidden,true);assert.equal(message.textContent,'');assert.equal(h.requests.length,before);await h.submit(form);assert.equal(h.navigations.length,1);const next=h.navigations[0];assert.equal(next.tab,'reports');for(const[key,value]of Object.entries({from:'2026-11-02',to:'2026-11-04',source_id:'source-a',currency:'USD'}))assert.equal(next.params.get(key),value);assert.equal(h.requests.length,before,'A valid submit requests navigation; it must not independently duplicate the route fetch.');h.state.params=next.params;await h.load();const scoped=h.page.querySelectorAll('tbody')[0].querySelectorAll('tr');assert.equal(scoped.length,1);assert.ok(scoped[0].textContent.includes('REPORT-WEEK'));const oneSided=h.page.querySelector('[data-op-form=filters]'),oneFrom=oneSided.querySelector('[name=from]'),oneTo=oneSided.querySelector('[name=to]');oneFrom.value='2026-11-10';oneTo.value='2026-11-01';await h.submit(oneSided);assert.equal(h.navigations.length,1);oneFrom.value='';await h.dispatch(oneFrom,'change');assert.equal(oneSided.querySelector('[data-ops-filter-error]').hidden,true);assert.equal(oneTo.hasAttribute('aria-invalid'),false);await h.submit(oneSided);assert.equal(h.navigations.length,2);assert.equal(h.navigations[1].params.has('from'),false);assert.equal(h.navigations[1].params.get('to'),'2026-11-01');}finally{h.close();}}}finally{store.close();}});
await test('actual emitted core errors offer clear-filter navigation only for a parameterized 422 and preserve sign-in and retry semantics',async()=>{for(const lang of ['en','zh'])for(const[status,params]of [[422,'q=synthetic&page=invalid'],[422,''],[401,'q=synthetic'],[403,'q=synthetic'],[500,'q=synthetic']]){const h=coreHarness(lang,{fetchResult:async()=>new Response(JSON.stringify({error:{code:'SYNTHETIC_ERROR',message:'Synthetic rejected scope'}}),{status,headers:{'content-type':'application/json'}})});h.core.state.tab='customers';h.core.state.params=new URLSearchParams(params);h.location.hash='#customers'+(params?'?'+params:'');await h.core.loadPage();const page=h.getNode('workspace-page'),clear=page.querySelector('[data-clear-filters]');assert.equal(page.getAttribute('aria-busy'),'false');assert.ok(page.querySelector('.error-banner').textContent.length>0);assert.equal(Boolean(clear),status===422&&Boolean(params));assert.equal(h.requests.length,1);if(status===401){assert.equal(page.querySelector('a[href="/admin"]').textContent,h.core.t('signIn'));assert.equal(page.querySelector('[data-refresh]'),null);}else assert.ok(page.querySelector('[data-refresh]'));if(clear){assert.equal(clear.tagName,'button');assert.equal(clear.getAttribute('type'),'button');assert.equal(clear.textContent,h.core.t('clearFilters'));await h.click(clear);assert.equal(h.location.hash,'#customers');assert.equal(h.requests.length,1,'Clear filters must reuse route navigation rather than issue a second request with the rejected parameters.');}}});

